source.benchmark_patch:
--- a/examples/decimal_bench.rs
+++ b/examples/decimal_bench.rs
@@ -147,7 +147,12 @@
         }
         Ok(count)
     };
-    // Generic IN only: keep fresh plans per sample while allowing longer runs.
+    let replay_order = std::env::var("DECIMAL_BENCH_IN_REPLAY_ORDER")
+        .unwrap_or_else(|_| "adjacent".into());
+    if !matches!(replay_order.as_str(), "adjacent" | "sweep") {
+        return Err("DECIMAL_BENCH_IN_REPLAY_ORDER must be adjacent or sweep".into());
+    }
+    // Diagnostic only: retain native randomized plans across four executions.
     let warmups = timing_count("DECIMAL_BENCH_IN_WARMUPS", WARMUPS)?;
     let samples = timing_count("DECIMAL_BENCH_IN_SAMPLES", SAMPLES)?;
     let mut results = Vec::new();
@@ -437,10 +442,23 @@
                     if phase == "planning" {
                         perf_command(b"disable\n")?;
                     }
+                    let mut plan_indices = Vec::with_capacity(4 * samples);
+                    if replay_order == "adjacent" {
+                        for index in 0..samples {
+                            plan_indices.extend(std::iter::repeat_n(index, 4));
+                        }
+                    } else {
+                        for reverse in [false, true, true, false] {
+                            for offset in 0..samples {
+                                plan_indices.push(if reverse { samples - 1 - offset } else { offset });
+                            }
+                        }
+                    }
                     if phase == "execution" {
                         perf_command(b"enable\n")?;
                     }
-                    for plan in plans {
+                    for &index in &plan_indices {
+                        let plan = Arc::clone(&plans[index]);
                         let start = Instant::now();
                         let counts = consume(ctx, plan).await?;
                         execution_ms.push(start.elapsed().as_secs_f64() * 1000.0);
@@ -449,6 +467,8 @@
                     if phase == "execution" {
                         perf_command(b"disable\n")?;
                     }
+                    result["sample_plan_indices"] = json!(plan_indices);
+                    result["replay_order"] = json!(replay_order);
                     result["planning_samples_ms"] = json!(planning_ms);
                     result["samples_ms"] = json!(execution_ms);
                 }
